205	bool PhysicsHelper::isPolygonConvex(const Vec2* verts, int count)
206	{
207	    if (verts == nullptr || count < 3)
208	        return false;
209	
210	    int sign = 0;
211	    for (int i = 0; i < count; ++i)
212	    {
213	        const Vec2& a = verts[i];
214	        const Vec2& b = verts[(i + 1) % count];
215	        const Vec2& c = verts[(i + 2) % count];
216	        const float turn = (b - a).cross(c - b);
217	
218	        if (turn > kHelperEpsilon)
219	        {
220	            if (sign < 0)
221	                return false;
222	            sign = 1;
223	        }
224	        else if (turn < -kHelperEpsilon)
225	        {
226	            if (sign > 0)
227	                return false;
228	            sign = -1;
229	        }
230	    }
231	
232	    return sign != 0;
233	}
